const {chromium} = require('playwright');
const out = process.argv[2];
const BASE = 'http://localhost:3107';
const mock = () => {
  const real = window.fetch;
  window.fetch = async (input, init) => {
    const u = String(input instanceof Request ? input.url : input);
    if (u.includes('/api/sandbox')) return new Response(JSON.stringify({sandboxId: 'sb_mock', previewUrl: '/workspace/preview?mock=1'}), {headers: {'content-type': 'application/json'}});
    if (u.includes('/api/auth/chatgpt/session')) return new Response(JSON.stringify({status: 'signed-out', available: false}), {headers: {'content-type': 'application/json'}});
    if (u.includes('/api/')) return new Response('blocked in ux check', {status: 500});
    return real(input, init);
  };
};
(async () => {
  const browser = await chromium.launch({executablePath: process.env.CHROME});
  const page = await browser.newPage({viewport: {width: 1280, height: 800}});
  await page.addInitScript(mock);
  const r = {};
  await page.goto(BASE + '/');
  await page.getByRole('button', {name: 'Round the corners of every button'}).click();
  r.composer = await page.getByRole('textbox', {name: 'Message'}).innerText();
  await page.screenshot({path: out + '/1-landing.png'});
  await page.getByRole('textbox', {name: 'Message'}).press('Enter');
  await page.waitForURL(/workspace/);
  await page.waitForTimeout(6000);
  r.newProject = {
    url: page.url(),
    title: await page.evaluate(() => localStorage.getItem('betterlook.title')),
    previewRegions: await page.getByRole('region', {name: 'Preview'}).count(),
    connectModels: await page.getByRole('button', {name: 'Connect models'}).count(),
    notice: await page.getByText(/key to send/).allInnerTexts(),
    navText: (await page.locator('header').first().innerText()).slice(0, 200),
  };
  await page.screenshot({path: out + '/2-chat-only.png'});
  // Reopen with a saved chat that changed files.
  await page.evaluate(() => {
    const msgs = [
      {id: 'u1', role: 'user', parts: [{type: 'text', text: 'Round the corners of every button'}]},
      {id: 'a1', role: 'assistant', parts: [{type: 'text', text: 'Rounded the buttons.'}, {type: 'data-diff', id: 'd', data: {diff: 'diff --git a/src/App.tsx b/src/App.tsx', filesTouched: ['src/App.tsx']}}]},
    ];
    localStorage.setItem('betterlook.chat', JSON.stringify(msgs));
  });
  await page.goto(BASE + '/workspace');
  await page.waitForTimeout(6000);
  r.reopen = {
    previewRegions: await page.getByRole('region', {name: 'Preview'}).count(),
    tabs: await page.getByRole('tab').allInnerTexts(),
    placeholderVisible: await page.getByText('Your preview will appear here').isVisible().catch(() => false),
    navText: (await page.locator('header').first().innerText()).slice(0, 200),
  };
  await page.screenshot({path: out + '/3-split-preview.png'});
  await page.getByRole('tab', {name: 'Settings'}).click();
  r.settings = {
    connectVisible: await page.getByRole('button', {name: 'Connect models'}).isVisible(),
    frameVisible: await page.getByTitle('App preview').isVisible(),
  };
  await page.screenshot({path: out + '/4-settings.png'});
  await page.getByRole('button', {name: 'Connect models'}).click();
  await page.waitForTimeout(800);
  await page.screenshot({path: out + '/5-settings-popover.png'});
  await page.keyboard.press('Escape');
  await page.getByRole('tab', {name: 'Preview'}).click();
  // Mobile switch.
  await page.setViewportSize({width: 390, height: 800});
  await page.waitForTimeout(500);
  const chatVisible = () => page.getByRole('region', {name: 'Chat'}).isVisible();
  const previewVisible = () => page.getByRole('region', {name: 'Preview'}).isVisible();
  r.mobile = {before: {chat: await chatVisible(), preview: await previewVisible()}};
  await page.getByRole('radio', {name: 'Preview'}).click().catch(async () => page.getByText('Preview', {exact: true}).first().click());
  await page.waitForTimeout(300);
  r.mobile.after = {chat: await chatVisible(), preview: await previewVisible()};
  await page.screenshot({path: out + '/6-mobile-preview.png'});
  console.log(JSON.stringify(r, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
